import type { LibraryProjectPreview } from '../types/project-library';
import {
  ProjectPreviewCache,
  type CachedProjectPreview,
} from '../storage/library/ProjectPreviewCache';
import type { ProjectLibrary } from './ProjectLibrary';
import type { ProjectRuntimeService } from './ProjectRuntimeService';
import type { StaticLibraryPreviews } from './StaticLibraryPreviews';
import { ProjectScreenshotService } from './ProjectScreenshotService';
import type { TelemetryService } from './TelemetryService';
import { createLogger } from '../utils/logger';

const log = createLogger('ProjectCardPreviews');

export class ProjectCardPreviews {
  private readonly pending = new Map<
    string,
    Promise<LibraryProjectPreview | null>
  >();
  private readonly cache: ProjectPreviewCache;
  private readonly screenshots = new ProjectScreenshotService();

  constructor(
    private readonly services: {
      library: ProjectLibrary;
      runtime: ProjectRuntimeService;
      previews: StaticLibraryPreviews;
      telemetry?: TelemetryService;
    },
  ) {
    this.cache = new ProjectPreviewCache(services.library.registry.root);
  }

  get(projectId: string): Promise<LibraryProjectPreview | null> {
    this.services.library.registry.get(projectId);
    const existing = this.pending.get(projectId);
    if (existing) return existing;
    const pending = this.load(projectId);
    this.pending.set(projectId, pending);
    void pending
      .finally(() => this.pending.delete(projectId))
      .catch(() => undefined);
    return pending;
  }

  async close(): Promise<void> {
    await this.screenshots.close();
    await Promise.allSettled(this.pending.values());
  }

  private async load(projectId: string): Promise<LibraryProjectPreview | null> {
    const { library, runtime, previews, telemetry } = this.services;
    const project = library.registry.get(projectId);
    let cached: CachedProjectPreview | null = null;
    const startedAt = Date.now();
    try {
      const stored = await this.cache.read(projectId);
      if (stored?.projectPath === project.projectPath) cached = stored;
      let url = await runtime.originalPreviewUrl(projectId);
      let sourceKey = 'original';
      let label = 'Original';
      if (!url) {
        if (cached?.sourceKey === 'original') return this.publicPreview(cached);
        const first = (await library.listVariants(projectId))
          .filter(
            (entry) =>
              entry.manifest.projectKind === 'fresh' && entry.hasStaticPreview,
          )
          .sort((a, b) =>
            a.manifest.createdAt.localeCompare(b.manifest.createdAt),
          )[0];
        if (!first) return null;
        const { manifest } = first;
        sourceKey = JSON.stringify([
          manifest.sessionId,
          manifest.variantId,
          manifest.tree?.treeSha,
          manifest.statusChangedAt,
        ]);
        label = manifest.label;
        if (cached?.sourceKey !== sourceKey) cached = null;
        if (cached) return { ...this.publicPreview(cached), label };
        url = await previews.url({
          projectId,
          sessionId: manifest.sessionId,
          variantId: manifest.variantId,
        });
      }
      if (cached?.sourceKey === sourceKey)
        return this.publicPreview(cached);
      const preview = {
        sourceKey,
        projectPath: project.projectPath,
        dataUrl: await this.screenshots.capture(url),
        label,
        capturedAt: new Date().toISOString(),
      };
      await this.cache.write(projectId, preview);
      telemetry?.trackLibraryOperation({
        operation: 'thumbnail_capture',
        outcome: 'completed',
        durationMs: Date.now() - startedAt,
      });
      return this.publicPreview(preview);
    } catch (error) {
      log.warn(
        'Project image is unavailable; retaining its last capture',
        error,
      );
      telemetry?.trackLibraryOperation({
        operation: 'thumbnail_capture',
        outcome: 'failed',
        durationMs: Date.now() - startedAt,
      });
      return cached ? this.publicPreview(cached) : null;
    }
  }

  private publicPreview(preview: CachedProjectPreview): LibraryProjectPreview {
    return {
      dataUrl: preview.dataUrl,
      label: preview.label,
      capturedAt: preview.capturedAt,
    };
  }
}
